#!/usr/bin/env python3
"""One-line check: recompute c46 on the PINNED R1 second witness from its mixture definition
(minimal independent engine, exact Fraction marginals + prime-exponent log signs), print decimal."""
import math
from fractions import Fraction
from math import lcm

def pe(n):
    e={}; d=2
    while d*d<=n:
        while n%d==0: e[d]=e.get(d,0)+1; n//=d
        d+=1
    if n>1: e[n]=e.get(n,0)+1
    return e

def Hvec(dist):
    den=1
    for p in dist.values(): den=lcm(den,p.denominator)
    v={}
    for pr,ex in pe(den).items(): v[pr]=v.get(pr,Fraction(0))+Fraction(ex)
    for m,p in dist.items():
        n=int(p*den)
        if n==0: continue
        for pr,ex in pe(n).items(): v[pr]=v.get(pr,Fraction(0))-Fraction(ex*n,den)
    return {p:c for p,c in v.items() if c!=0}

def marg(dist,sub):
    out={}
    for m,p in dist.items():
        k=m&sub; out[k]=out.get(k,Fraction(0))+p
    return out

def add(a,b):
    out=dict(a)
    for m,v in b.items(): out[m]=out.get(m,0)+v
    return {m:v for m,v in out.items() if v!=0}
def cmi(x,y,z): return {x|z:1,y|z:1,z:-1,x|y|z:-1}
ING = add(add(add(cmi(1,2,4),cmi(1,2,8)),{4:1,8:1,12:-1}),{1:-1,2:-1,3:1})
C46 = add(ING, cmi(4,8,2))

