dist = {0: Fraction(3,8), 15: Fraction(3,8), 5: Fraction(1,8), 9: Fraction(1,8)}
tot={}
for m in range(1,16):
    for pr,e in Hvec(marg(dist,m)).items():
        tot[pr]=tot.get(pr,Fraction(0))+Fraction(C46.get(m,0))*e
tot={p:c for p,c in tot.items() if c!=0}
# exact sign
from math import lcm as _l
B=1
for c in tot.values(): B=_l(B,c.denominator)
lhs=rhs=1
for p,c in sorted(tot.items()):
    a=c.numerator*(B//c.denominator)
    if a>0: lhs*=p**a
