#!/usr/bin/env python3
"""One-line check: cross-lineage convention drift probe. Tries all 48 variants
(2 string readings x 24 party relabelings) of the Q36-lineage 6-atom 291600-count witness
against the KB-pinned values N*Ing(corpus) = -7.455776108850990 / N*Q36 = +1.837778949756130
(pursuit-q-q36-analytic-rho4-constant-r2--finding--q36-convention-pinned-exactly-...).
Prints ANCHOR2_TRIED=48 MATCHES=<n> (0 = the anchor is not reachable from the BCWW-lineage
string/mask convention family; convention families have drifted across lineages)."""
from fractions import Fraction
import math
from math import lcm
from itertools import permutations


def pe(n):
    e = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            e[d] = e.get(d, 0) + 1
            n //= d
        d += 1
    if n > 1:
        e[n] = e.get(n, 0) + 1
    return e


def Hvec(dist):
    den = 1
    for p in dist.values():
        den = lcm(den, p.denominator)
    v = {}
    for pr, ex in pe(den).items():
        v[pr] = v.get(pr, Fraction(0)) + Fraction(ex)
    for m, p in dist.items():
        n = int(p * den)
        if n == 0:
            continue
        for pr, ex in pe(n).items():
            v[pr] = v.get(pr, Fraction(0)) - Fraction(ex * n, den)
    return {p: c for p, c in v.items() if c != 0}


def marg(dist, sub):
    out = {}
    for m, p in dist.items():
        k = m & sub
        out[k] = out.get(k, Fraction(0)) + p
    return out


counts = {"0000": 288938, "1010": 1080, "0100": 1080, "1011": 480, "0110": 9, "1111": 13}
N = 291600
ING_corpus = {5: 1, 9: 1, 6: 1, 10: 1, 12: 1, 3: -1, 4: -1, 8: -1, 13: -1, 14: -1}


def add(a, b):
    out = dict(a)
    for m, v in b.items():
        out[m] = out.get(m, 0) + v
    return {m: v for m, v in out.items() if v != 0}


def cmi(x, y, z):
    return {x | z: 1, y | z: 1, z: -1, x | y | z: -1}


Q36 = add(ING_corpus, add(add(cmi(1, 8, 4), cmi(2, 4, 8)), cmi(2, 8, 4)))


def val(coeffs, V):
    tot = {}
    for m, c in coeffs.items():
        for pr, e in V[m].items():
            tot[pr] = tot.get(pr, Fraction(0)) + Fraction(c) * e
    return {p: c for p, c in tot.items() if c != 0}


def f(v):
    return sum(float(c) * math.log2(p) for p, c in v.items())


t1, t2 = -7.455776108850990, +1.837778949756130
matches = 0
tried = 0
for name, mf in (("rightmost=A", lambda s: sum((1 << i) for i, ch in enumerate(s) if ch == "1")),
                 ("leftmost=A", lambda s: sum((1 << (3 - i)) for i, ch in enumerate(s) if ch == "1"))):
    dist0 = {mf(s): Fraction(c, N) for s, c in counts.items()}
    for perm in permutations(range(4)):
        def rl(m):
            return sum(1 << perm[b] for b in range(4) if m & (1 << b))
        dist = {rl(m): p for m, p in dist0.items()}
        V = {m: Hvec(marg(dist, m)) for m in range(1, 16)}
        tried += 1
        i6, q6 = f(val(ING_corpus, V)) * N, f(val(Q36, V)) * N
        if abs(i6 - t1) < 1e-6 and abs(q6 - t2) < 1e-6:
            matches += 1
print(f"ANCHOR2_TRIED={tried} MATCHES={matches}")

