#!/usr/bin/env python3
"""Exact-rational copy-lemma LP engine (root-built, calibrated) for the BCWW repair run.

Semantics (lineage-standard):
- Variables: subset entropies h_S, S nonempty subset of V (base ABCD + copy auxiliaries).
- Elemental Shannon cone: I(i;j|K) >= 0 for unordered pairs {i,j}, K subset of V \\ {i,j};
  plus H(i | V\\{i}) >= 0. (n=4 -> 28 rows; n=5 -> 85; n=6 -> 246; n=7 -> 679; matches KB counts.)
- Copy lemma, Zhang-Yeung semantics: copy(Y | Z) adds R with
    (a) joint match:   h_{W u R} = h_{W u Y}   for all W subseteq Z
    (b) independence:  I(R; X | Z) = 0          for all X subseteq V_base \\ (Y u Z), X != {}
  (equality rows; V_base = the four base variables existing before this copy step — copies of
  copies chain naturally by applying the step to the then-current variable set.)
- Normalization row: h_V = 1.
- LP: minimize c.h subject to rows; exact Fractions, two-phase simplex, Bland's rule.

Calibration anchors (KB-pinned):
- depth 0, Ingleton functional (paper convention), min = -1/4 exactly.
- depth 1: best over the 65 copy schemes = -1/6 exactly (DFZ's published level-1 number).
- depth 1, Zhang-Yeung functional: min = 0 for exactly 6 of 65 schemes (DFZ's claim).

Usage: python3 exact_lp.py [--selftest]
"""
import sys
from fractions import Fraction
from itertools import combinations

BASE = ["A", "B", "C", "D"]


def subsets(xs):
    out = []
    for k in range(len(xs) + 1):
        out.extend(combinations(xs, k))
    return out


class EntropyLP:
    def __init__(self, varnames):
        self.vars = list(varnames)          # e.g. BASE + ["R1"]
        self.nv = len(self.vars)
        self.coords = [(frozenset(S), ) for S in subsets(self.vars)[1:]]  # placeholder
        self.idx = {}
        for S in subsets(self.vars):
            if S:
                self.idx[frozenset(S)] = len(self.idx)
        self.nc = len(self.idx)
        self.rows = []     # (dict coord->coeff, rhs Fraction, kind)
        self._elemental()

    def _elemental(self):
        V = self.vars
        for i, j in combinations(V, 2):
            rest = [x for x in V if x not in (i, j)]
            for K in subsets(rest):
                row = {self.idx[frozenset((i,) + K)]: Fraction(1),
                       self.idx[frozenset((j,) + K)]: Fraction(1)}
                if K:
                    row[self.idx[frozenset(K)]] = row.get(self.idx[frozenset(K)], Fraction(0)) - Fraction(1)
                row[self.idx[frozenset((i, j) + K)]] = row.get(self.idx[frozenset((i, j) + K)], Fraction(0)) - Fraction(1)
                self.rows.append(({k: v for k, v in row.items() if v}, Fraction(0), "ge"))
        for i in V:
            rest = frozenset(V) - {i}
            row = {self.idx[frozenset(V)]: Fraction(1)}
            if rest:
                row[self.idx[rest]] = Fraction(-1)
            self.rows.append((row, Fraction(0), "ge"))

    def add_copy(self, R, Y, Z):
        """copy(Y | Z) with new variable R. Y,Z disjoint subsets of current vars."""
        assert R in self.vars and R not in Y and R not in Z
        for W in subsets(list(Z)):
            if not W:
                continue
            r = {self.idx[frozenset(W) | {R}]: Fraction(1),
                 self.idx[frozenset(W) | frozenset(Y)]: Fraction(-1)}
            self.rows.append((r, Fraction(0), "eq"))
        others = [x for x in BASE if x not in Y and x not in Z]
        for X in subsets(others):
            if not X:
                continue
            r = {self.idx[frozenset(Z) | {R} | frozenset(X)]: Fraction(1),
                 self.idx[frozenset(Z)]: Fraction(-1),
                 self.idx[frozenset(Z) | {R}]: Fraction(-1),
                 self.idx[frozenset(Z) | frozenset(X)]: Fraction(-1)}
            self.rows.append(({k: v for k, v in r.items() if v}, Fraction(0), "eq"))

    def normalize(self):
        self.rows.append(({self.idx[frozenset(self.vars)]: Fraction(1)}, Fraction(1), "eq"))

    # ---------- exact two-phase simplex (Bland) ----------
    def solve(self, c):
        """min c.h over rows; c = dict coord->Fraction. Returns (status, value, h, duals)."""
        m = len(self.rows)
        n = self.nc
        # build tableau: rows ge 0 -> slack; eq -> artificial
        A = [[Fraction(0)] * n for _ in range(m)]
        b = [Fraction(0)] * m
        ge_rows, eq_rows = [], []
        for r, (row, rhs, kind) in enumerate(self.rows):
            b[r] = rhs
            for j, v in row.items():
                A[r][j] = v
            (ge_rows if kind == "ge" else eq_rows).append(r)
        # shift ge rows to >= 0 form (rhs are 0 or 1 for normalization: h_V = 1 as eq)
        # Standard form: min c x, A_ge x >= 0  ->  -A x <= 0;  eq x = rhs.
        # Use: constraints  A_ge x - s = 0, s >= 0 ;  A_eq x = b_eq.
        ncols = n + len(ge_rows)
        rowsT = []
        rhs = []
        for k, r in enumerate(ge_rows):
            row = [-A[r][j] for j in range(n)] + [Fraction(0)] * len(ge_rows)
            row[n + k] = Fraction(-1)
            rowsT.append(row); rhs.append(Fraction(0))
        for r in eq_rows:
            row = [A[r][j] for j in range(n)] + [Fraction(0)] * len(ge_rows)
            rowsT.append(row); rhs.append(b[r])
        cost = [c.get(j, Fraction(0)) if j < n else Fraction(0) for j in range(ncols)]
        val, x, tab = _simplex(rowsT, rhs, cost)
        if val is None:
            return ("infeasible", None, None, None)
        h = {j: x[j] for j in range(n)}
        return ("opt", val, h, tab)


def _simplex(A, b, c):
    """Two-phase simplex on min c.x s.t. Ax=b, x>=0. Exact Fractions, Bland's rule."""
    m = len(A)
    n = len(A[0]) if m else len(c)
    # ensure b >= 0
    for i in range(m):
        if b[i] < 0:
            A[i] = [-v for v in A[i]]
            b[i] = -b[i]
    # phase 1: add artificials
    N = n + m
    T = [A[i] + [Fraction(1) if k == i else Fraction(0) for k in range(m)] + [b[i]] for i in range(m)]
    basis = [n + i for i in range(m)]
    pcost = [Fraction(0)] * n + [Fraction(1)] * m
    if _phase(T, basis, pcost) is None:
        return None, None, None
    # drive artificials out / degenerate ok; forbid artificials re-entering: cost 0 keeps them at 0
    if any(abs(T[i][N]) > 0 for i in range(m)):
        # artificial basic with positive value -> infeasible
        return None, None, None
    # phase 2
    c2 = list(c) + [Fraction(0)] * m
    if _phase(T, basis, c2) is None:
        return None, None, None
    x = [Fraction(0)] * n
    for i, bi in enumerate(basis):
        if bi < n:
            x[bi] = T[i][N]
    val = sum(c[j] * x[j] for j in range(n))
    return val, x, T


def _phase(T, basis, cost):
    m = len(T)
    N = len(T[0]) - 1
    it = 0
    while True:
        it += 1
        if it > 20000:
            return None
        # reduced costs
        y = [cost[basis[i]] for i in range(m)]
        red = []
        for j in range(N + 1 - 1):  # all structural columns
            cj = cost[j] if j < len(cost) else Fraction(0)
            z = cj - sum(y[i] * T[i][j] for i in range(m))
            red.append(z)
        # Bland: smallest index with negative reduced cost
        enter = None
        for j, z in enumerate(red):
            if z < 0:
                enter = j
                break
        if enter is None:
            return T
        leave = None
        best = None
        for i in range(m):
            if T[i][enter] > 0:
                ratio = T[i][N] / T[i][enter]
                if best is None or ratio < best or (ratio == best and basis[i] < basis[leave]):
                    best, leave = ratio, i
        if leave is None:
            return None  # unbounded
        piv = T[leave][enter]
        T[leave] = [v / piv for v in T[leave]]
        for i in range(m):
            if i != leave and T[i][enter] != 0:
                f = T[i][enter]
                T[i] = [T[i][j] - f * T[leave][j] for j in range(N + 1)]
        basis[leave] = enter
    return T


# ---------- functionals (paper convention, masks A=1,B=2,C=4,D=8) ----------
def add(a, b):
    out = dict(a)
    for m, v in b.items():
        out[m] = out.get(m, 0) + v
    return {m: v for m, v in out.items() if v != 0}


def cmi(x, y, z):
    return {x | z: 1, y | z: 1, z: -1, x | y | z: -1}


ING = add(add(add(cmi(1, 2, 4), cmi(1, 2, 8)), {4: 1, 8: 1, 12: -1}), {1: -1, 2: -1, 3: 1})
ZY = add(add(ING, cmi(4, 8, 2)), {k: 2 * v for k, v in cmi(4, 8, 2).items()})  # placeholder, fixed below
# Zhang-Yeung functional: 2I(C;D) <= I(C;D|A)+I(C;D|B)+I(A;B|C)+I(A;B|D)+I(A;B)
ZY = add(add(add(cmi(4, 8, 1), cmi(4, 8, 2)), add(cmi(1, 2, 4), cmi(1, 2, 8))), {1: 1, 2: 1, 3: -1})
# = [I(C;D|A)+I(C;D|B)+I(A;B|C)+I(A;B|D)] + I(A;B) - ... careful: ZY is an INEQUALITY
# 2 I(C;D) <= I(C;D|A)+I(C;D|B)+I(A;B|C)+I(A;B|D)+I(A;B); the LP objective is the violation
# lhs-rhs <= 0 i.e. we minimize f = 2I(C;D) - I(C;D|A)-I(C;D|B)-I(A;B|C)-I(A;B|D)-I(A;B) and
# ZY is PROVEN iff min f = 0. Build f directly:
ZY = add(add({4: 2, 8: 2, 12: -2}, {k: -v for k, v in add(cmi(4, 8, 1), cmi(4, 8, 2)).items()}),
         {k: -v for k, v in add(add(cmi(1, 2, 4), cmi(1, 2, 8)), {1: 1, 2: 1, 3: -1}).items()})

MASK2VARS = {1: "A", 2: "B", 4: "C", 8: "D", 3: ("A", "B"), 5: ("A", "C"), 9: ("A", "D"),
             6: ("B", "C"), 10: ("B", "D"), 12: ("C", "D"), 7: ("A", "B", "C"), 11: ("A", "B", "D"),
             13: ("A", "C", "D"), 14: ("B", "C", "D"), 15: ("A", "B", "C", "D")}


def coeffs_to_c(lp, coeffs):
    out = {}
    for m, v in coeffs.items():
        out[lp.idx[frozenset(MASK2VARS[m])]] = Fraction(v)
    return out


def depth0(func):
    lp = EntropyLP(BASE)
    lp.normalize()
    st, val, h, tab = lp.solve(coeffs_to_c(lp, func))
    return val


def depth1_all(func):
    """All 65 schemes copy(Y|Z), Y,Z disjoint nonempty-Y subsets of BASE. Returns list of values."""
    res = []
    for Y in subsets(BASE)[1:]:
        for Z in subsets([x for x in BASE if x not in Y]):
            if not Z:
                continue
            lp = EntropyLP(BASE + ["R"])
            lp.add_copy("R", tuple(Y), tuple(Z))
            lp.normalize()
            st, val, h, tab = lp.solve(coeffs_to_c(lp, func))
            res.append((val, tuple(Y), tuple(Z)))
    return res


if __name__ == "__main__":
    print("depth0 Ingleton:", depth0(ING), "(expect -1/4)")
    r = depth1_all(ING)
    best = min(x[0] for x in r)
    print("depth1 Ingleton best:", best, f"(expect -1/6); schemes at best: {sum(1 for x in r if x[0]==best)}/{len(r)} total schemes")
    z = depth1_all(ZY)
    zeros = [x for x in z if x[0] == 0]
    print("depth1 ZY min:", min(x[0] for x in z), "zero-schemes:", len(zeros), "(expect 0 and exactly 6)")

