#!/usr/bin/env python3
"""Convention lock for the BCWW 4.6 repair run.

Locks, in EXACT rational arithmetic (prime-exponent log vectors, no float sign decisions):
  1. The 5-atom classical witness vector (uniform on {0001,0010,0011,0111,1000}, strings (A,B,C,D)).
  2. The GHZ4-mixture second witness: identifies which mixture reproduces R1's "+0.113302 bits"
     violation of (4.6), among: white-noise (1-k/12)GHZ4+(k/12)I/16 (k=0..12), the Linden mixture
     0.5 GHZ4 + 0.25|0101> + 0.25|1001>, and its 24 party relabelings.
Anchors (KB-pinned, used to calibrate conventions, NOT re-verified as claims):
  - c46 on the 5-atom witness = (14 - 9 log2 3)/5 = -0.052932501298081 bits
    (KB: pursuit-arena-v9b1-q36-corpus-b--finding--five-atom-counterexample-bcww-2015-4-6-...)
  - corpus-convention Ing on the 291600-count 6-atom witness: N*Ing = -7.455776108850990
    (KB: pursuit-q-q36-analytic-rho4-constant-r2--finding--q36-convention-pinned-exactly-...)

Prints one decisive line per anchor; writes work/lock/witnesses.json.
"""
import json
import math
import os
from fractions import Fraction
from itertools import permutations

HERE = os.path.dirname(os.path.abspath(__file__))
OUT = os.path.join(HERE, "witnesses.json")

# ---- masks and names (bit A=1, B=2, C=4, D=8; string position 0 = A) ----
NAMES = {1: "A", 2: "B", 4: "C", 8: "D", 3: "AB", 5: "AC", 9: "AD", 6: "BC", 10: "BD", 12: "CD",
         7: "ABC", 11: "ABD", 13: "ACD", 14: "BCD", 15: "ABCD"}


def str_mask(s):
    m = 0
    for i, ch in enumerate(s):
        if ch == "1":
            m |= 1 << (3 - i)  # position 0 = A = bit 3
    return m


def prime_exponents(n):
    e = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            e[d] = e.get(d, 0) + 1
            n //= d
        d += 1
    if n > 1:
        e[n] = e.get(n, 0) + 1
    return e


def entropy_vec(dist):
    """dist: dict mask(Fraction) -> Fraction prob. Returns {prime: Fraction coeff} for H = sum e_p log2 p."""
    v = {}
    D = Fraction(1)
    for p in dist.values():
        D *= 1
    # H = -sum p log2 p ; p = n/d common denominator d
    d = Fraction(1)
    for p in dist.values():
        d = d if p.denominator % d == 0 or d % p.denominator == 0 else d
    # simpler: common denominator = lcm
    from math import gcd
    den = 1
    for p in dist.values():
        g = gcd(den, p.denominator)
        den = den * p.denominator // g
    # +1 * log2(den)
    for pr, ex in prime_exponents(den).items():
        v[pr] = v.get(pr, Fraction(0)) + Fraction(ex)
    for mask, p in dist.items():
        n = p * den
        assert n.denominator == 1
        n = int(n)
        if n == 0:
            continue
        for pr, ex in prime_exponents(n).items():
            v[pr] = v.get(pr, Fraction(0)) - Fraction(ex * n, den)
    return {pr: c for pr, c in v.items() if c != 0}


def eval_float(vec):
    return sum(float(c) * math.log2(p) for p, c in vec.items())


def functional_value(coeffs, dists):
    """coeffs: {mask:int}, dists: {mask: entropy_vec}. Returns prime-exponent Fraction vector."""
    tot = {}
    for m, c in coeffs.items():
        for pr, e in dists[m].items():
            tot[pr] = tot.get(pr, Fraction(0)) + Fraction(c) * e
    return {pr: c for pr, c in tot.items() if c != 0}


def sign_exact(vec):
    """Exact sign of sum q_p log2 p: compare prod p^(a_p*B/b_p) vs 1 in big ints."""
    from math import lcm
    dens = [c.denominator for c in vec.values()]
    B = 1
    for d in dens:
        B = lcm(B, d)
    lhs = 1  # p^(positive parts)
    rhs = 1
    for p, c in vec.items():
        a = c.numerator * (B // c.denominator)
        if a > 0:
            lhs *= p ** a
        elif a < 0:
            rhs *= p ** (-a)
    return (lhs > rhs) - (lhs < rhs)


def decimal_str(vec, nd=12):
    return f"{eval_float(vec):.{nd}f}"


# ---- functionals (paper convention) ----
def ing_abcd():
    """Ingleton(A:B;C,D) = I(A;B|C)+I(A;B|D)+I(C;D)-I(A;B) as subset-entropy coefficients."""
    c = {}
    def add(m, k):
        c[m] = c.get(m, 0) + k
    for m in (5, 6):
        add(m, 1)          # H(AC)+H(BC)
    add(4, -1); add(7, -1)  # -H(C)-H(ABC)
    for m in (9, 10):
        add(m, 1)          # H(AD)+H(BD)
    add(8, -1); add(11, -1)  # -H(D)-H(ABD)
    add(4, 1); add(8, 1); add(12, -1)  # +I(C;D)
    add(1, -1); add(2, -1); add(3, 1)  # -I(A;B)
    return c


def cmi(x, y, z):
    """I(X;Y|Z) coefficients."""
    xz = x | z; yz = y | z; xyz = x | y | z
    return {xz: 1, yz: 1, z: -1, xyz: -1}


def add_dicts(a, b, k=1):
    out = dict(a)
    for m, v in b.items():
        out[m] = out.get(m, 0) + k * v
    return {m: v for m, v in out.items() if v != 0}


ING = ing_abcd()
C46 = add_dicts(ING, cmi(4, 8, 2))  # + I(C:D|B)

# sanity: c46 must equal -L for the printed BCWW (4.6)
L = {11: 1, 7: 1, 14: 1, 10: -2, 6: -2, 12: 1, 9: -1, 5: -1, 3: -1, 2: 2, 1: 1}
NEG_L = {m: -v for m, v in L.items()}
assert C46 == NEG_L, (C46, NEG_L)

# corpus-convention Ingleton for anchor 2: Ing(C:D;A,B) = relabel (A,B,C,D)->(C,D,A,B)
RELAB = {1: 4, 2: 8, 4: 1, 8: 2}
def relabel_mask(m):
    out = 0
    for bit, nb in RELAB.items():
        if m & bit:
            out |= nb
    return out
ING_CORPUS = {}
for m, v in ING.items():
    ING_CORPUS[relabel_mask(m)] = ING_CORPUS.get(relabel_mask(m), 0) + v
# KB pinned: c_Ing(corpus) = {AC:+1,AD:+1,BC:+1,BD:+1,CD:+1,AB:-1,C:-1,D:-1,ACD:-1,BCD:-1}
expect_corpus = {5: 1, 9: 1, 6: 1, 10: 1, 12: 1, 3: -1, 4: -1, 8: -1, 13: -1, 14: -1}
assert ING_CORPUS == expect_corpus, (ING_CORPUS, expect_corpus)

# ---- distributions ----
def marginal(dist, sub):
    """dist: {mask: Fraction}; sub: mask of kept variables. Returns marginal dist."""
    out = {}
    for m, p in dist.items():
        k = m & sub
        out[k] = out.get(k, Fraction(0)) + p
    return out


def full_vector(dist):
    return {m: entropy_vec(marginal(dist, m)) for m in range(1, 16)}


F5 = Fraction(1, 5)
W1 = {str_mask(s): F5 for s in ("0001", "0010", "0011", "0111", "1000")}
V1 = full_vector(W1)
val5 = functional_value(C46, V1)
s5 = sign_exact(val5)
print(f"ANCHOR1 5-atom c46 = {decimal_str(val5)} bits (sign {s5}); "
      f"expect -0.052932501298 (KB (14-9log2 3)/5)")

# anchor 2: 6-atom 291600 witness, corpus-convention Ingleton
counts = {"0000": 288938, "1010": 1080, "0100": 1080, "1011": 480, "0110": 9, "1111": 13}
N = 291600
W6 = {str_mask(s): Fraction(c, N) for s, c in counts.items()}
V6 = full_vector(W6)
# N * Ing(corpus): multiply entropy by N -> scale vector by N (an integer: fine, Fractions)
ing6 = functional_value(ING_CORPUS, V6)
n_ing6 = {p: c * N for p, c in ing6.items()}
print(f"ANCHOR2 N*Ing(corpus) on 291600 witness = {decimal_str(n_ing6, 9)}; "
      f"expect -7.455776108 (KB convention pin)")
q36_corpus = add_dicts(ING_CORPUS, {**cmi(1, 8, 4), **{}})
# R(corpus) = I(A:D|C)+I(B:C|D)+I(B:D|C)
R = {}
for t in (cmi(1, 8, 4), cmi(2, 4, 8), cmi(2, 8, 4)):
    R = add_dicts(R, t)
q36v = add_dicts(ING_CORPUS, R)
q6 = functional_value(q36v, V6)
print(f"ANCHOR2b N*Q36(corpus) = {decimal_str({p: c * N for p, c in q6.items()}, 9)}; "
      f"expect +1.837778949 (KB)")

# ---- GHZ4 mixture candidates ----
ghz_marg = lambda sub: {0 & sub: Fraction(1, 2), sub: Fraction(1, 2)}  # 0^S and 1^S
# NOTE: 0 & sub = 0 -> mask 0 key is dropped by dict overwriting? handle: mask 0 valid key.
def mix_dist(comps):
    """comps: list of (weight Fraction, {mask: Fraction prob} classical marginal-on-full-space)."""
    out = {}
    for w, d in comps:
        for m, p in d.items():
            out[m] = out.get(m, Fraction(0)) + w * p
    return out

def classical_state(diag):
    """diag: {string: Fraction} classical diagonal state -> {mask: prob}"""
    return {str_mask(s): p for s, p in diag.items()}

results = {}
# (a) white-noise k/12
for k in range(0, 13):
    w_noise = Fraction(k, 12)
    w_ghz = 1 - w_noise
    comps = [(w_ghz, {0: Fraction(1, 2), 15: Fraction(1, 2)})]
    if w_noise > 0:
        u = {m: Fraction(1, 16) for m in range(16)}
        comps.append((w_noise, u))
    dist = mix_dist(comps)
    V = full_vector(dist)
    val = functional_value(C46, V)
    results[f"whitenoise_k{k}_of_12"] = (val, dist)

# (b) Linden state + 24 relabelings
def relabel_string(s, perm):
    """perm: tuple mapping new position i <- old position perm[i]."""
    return "".join(s[perm[i]] for i in range(4))

linden_base = {"GHZ": Fraction(1, 2)}
seen = {}
for perm in permutations(range(4)):
    s1 = relabel_string("0101", perm)
    s2 = relabel_string("1001", perm)
    key = tuple(sorted((s1, s2)))
    if key in seen:
        continue
    seen[key] = perm
    diag = {s1: Fraction(1, 4), s2: Fraction(1, 4)}
    dist = mix_dist([(Fraction(1, 2), {0: Fraction(1, 2), 15: Fraction(1, 2)}),
                     (Fraction(1, 4), classical_state({s1: Fraction(1)})),
                     (Fraction(1, 4), classical_state({s2: Fraction(1)}))])
    V = full_vector(dist)
    val = functional_value(C46, V)
    results[f"linden_pair_{s1}_{s2}"] = (val, dist)

